INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9701, 'តើរូបមន្តសម្រាប់គណនាផ្ទៃក្រឡាខាងនៃព្រីសត្រង់ដែលមានបរិមាត្របាត \(p\) និងកម្ពស់ \(h\) ណាត្រឹមត្រូវ?', 'g8-fbbe001236.svg', '["\\(S_L = p + h\\)", "\\(S_L = \\dfrac{p \\times h}{2}\\)", "\\(S_L = p \\times h\\)", "\\(S_L = S_B \\times h\\)"]', 2, NULL, 1, 'mcq', 'ផ្ទៃក្រឡាខាងនៃព្រីសត្រង់ស្មើបរិមាត្របាតគុណនឹងកម្ពស់ ៖ \(S_L = p \times h\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'easy', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9702, 'តើរូបមន្តសម្រាប់គណនាមាឌនៃព្រីសដែលមានផ្ទៃបាត \(S_B\) និងកម្ពស់ \(h\) ណាត្រឹមត្រូវ?', NULL, '["\\(V = \\dfrac{1}{3} S_B \\times h\\)", "\\(V = S_B \\times h\\)", "\\(V = \\dfrac{1}{2} S_B \\times h\\)", "\\(V = S_B + h\\)"]', 1, NULL, 1, 'mcq', 'មាឌព្រីសស្មើផ្ទៃបាតគុណនឹងកម្ពស់ ៖ \(V = S_B \times h\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'easy', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
