INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9703, 'តើរូបមន្តសម្រាប់គណនាមាឌនៃពីរ៉ាមីតដែលមានផ្ទៃបាត \(S_B\) និងកម្ពស់ \(h\) ណាត្រឹមត្រូវ?', 'g8-79409e22ad.svg', '["\\(V = \\dfrac{1}{2} S_B \\times h\\)", "\\(V = 3 S_B \\times h\\)", "\\(V = \\dfrac{1}{3} S_B \\times h\\)", "\\(V = S_B \\times h\\)"]', 2, NULL, 1, 'mcq', 'មាឌពីរ៉ាមីតស្មើមួយភាគបីនៃផ្ទៃបាតគុណនឹងកម្ពស់ ៖ \(V = \dfrac{1}{3} S_B \times h\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'easy', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9704, 'តើរូបមន្តសម្រាប់គណនាផ្ទៃក្រឡាខាងនៃពីរ៉ាមីតទៀងទាត់ដែលមានបរិមាត្របាត \(p\) និងអាប៉ូតែម \(a\) ណាត្រឹមត្រូវ?', NULL, '["\\(S_L = p \\times a\\)", "\\(S_L = 2 p \\times a\\)", "\\(S_L = \\dfrac{1}{2} p \\times a\\)", "\\(S_L = \\dfrac{1}{3} p \\times a\\)"]', 2, NULL, 1, 'mcq', 'ផ្ទៃក្រឡាខាងនៃពីរ៉ាមីតទៀងទាត់ស្មើកន្លះបរិមាត្របាតគុណនឹងអាប៉ូតែម ៖ \(S_L = \dfrac{1}{2} p \times a\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'easy', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
