INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9705, 'តើរូបមន្តគណនាផ្ទៃក្រឡាខាងនៃកោនដែលមានកាំបាត \(r\) និងប្រវែងជននី \(l\) ណាត្រឹមត្រូវ?', 'g8-b43b1cdb6c.svg', '["\\(S_L = 2\\pi r l\\)", "\\(S_L = \\pi r l\\)", "\\(S_L = \\dfrac{1}{3} \\pi r l\\)", "\\(S_L = \\pi r^2 l\\)"]', 1, NULL, 1, 'mcq', 'ផ្ទៃក្រឡាខាងនៃកោន ៖ \(S_L = \pi r l\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'easy', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9706, 'តើរូបមន្តគណនាមាឌកោនដែលមានកាំបាត \(r\) និងកម្ពស់ \(h\) ណាត្រឹមត្រូវ?', NULL, '["\\(V = \\dfrac{1}{2} \\pi r^2 h\\)", "\\(V = \\pi r^2 h\\)", "\\(V = \\dfrac{1}{3} \\pi r^2 h\\)", "\\(V = \\dfrac{4}{3} \\pi r^3\\)"]', 2, NULL, 1, 'mcq', 'មាឌកោនស្មើមួយភាគបីនៃមាឌស៊ីឡាំងដែលមានបាតនិងកម្ពស់ដូចគ្នា ៖ \(V = \dfrac{1}{3} \pi r^2 h\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'easy', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9707, 'គូបមួយមានរង្វាស់គែម \(a = 5\ \text{cm}\)។ គណនាមាឌនៃគូបនោះ។', NULL, '["\\(150\\ \\text{cm}^3\\)", "\\(75\\ \\text{cm}^3\\)", "\\(125\\ \\text{cm}^3\\)", "\\(25\\ \\text{cm}^3\\)"]', 2, NULL, 1, 'mcq', '\(V = a^3 = 5^3 = 125\ \text{cm}^3\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'easy', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9708, 'ប្រលេឡេពីប៉ែតកែងមួយមានបណ្តោយ \(8\ \text{cm}\), ទទឹង \(5\ \text{cm}\) និងកម្ពស់ \(4\ \text{cm}\)។ គណនាមាឌរបស់វា។', NULL, '["\\(160\\ \\text{cm}^3\\)", "\\(17\\ \\text{cm}^3\\)", "\\(40\\ \\text{cm}^3\\)", "\\(80\\ \\text{cm}^3\\)"]', 0, NULL, 1, 'mcq', '\(V = 8 \times 5 \times 4 = 160\ \text{cm}^3\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'easy', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9709, 'តើរូបមន្តគណនាមាឌស៊ីឡាំងដែលមានកាំបាត \(r\) និងកម្ពស់ \(h\) ណាត្រឹមត្រូវ?', NULL, '["\\(V = \\pi r^2 h\\)", "\\(V = 2\\pi r h\\)", "\\(V = \\dfrac{1}{3} \\pi r^2 h\\)", "\\(V = \\pi r h^2\\)"]', 0, NULL, 1, 'mcq', 'មាឌស៊ីឡាំង ៖ \(V = \pi r^2 h\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'easy', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9710, 'តើទំនាក់ទំនងរវាងកម្ពស់ \(h\), កាំបាត \(r\) និងជននី \(l\) នៃកោនណាត្រឹមត្រូវ?', NULL, '["\\(h^2 = l^2 + r^2\\)", "\\(l = r + h\\)", "\\(l^2 = h^2 - r^2\\)", "\\(l^2 = r^2 + h^2\\)"]', 3, NULL, 1, 'mcq', 'តាមពីតាក័រក្នុងត្រីកោណកែង ៖ \(l = \sqrt{r^2 + h^2}\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'easy', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9711, 'ព្រីសត្រង់មួយមានបាតជាត្រីកោណកែងដែលមានជ្រុងមុំកែង \(6\ \text{cm}\) និង \(8\ \text{cm}\)។ បើកម្ពស់ព្រីសគឺ \(10\ \text{cm}\) គណនាមាឌព្រីស។', NULL, '["\\(140\\ \\text{cm}^3\\)", "\\(480\\ \\text{cm}^3\\)", "\\(240\\ \\text{cm}^3\\)", "\\(120\\ \\text{cm}^3\\)"]', 2, NULL, 2, 'mcq', 'ផ្ទៃបាត ៖ \(S_B = \dfrac{6 \times 8}{2} = 24\ \text{cm}^2 \Rightarrow V = 24 \times 10 = 240\ \text{cm}^3\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9712, 'ព្រីសត្រង់មួយមានបាតជាត្រីកោណសម័ង្សជ្រុង \(5\ \text{cm}\) និងកម្ពស់ព្រីស \(12\ \text{cm}\)។ គណនាផ្ទៃក្រឡាខាងនៃព្រីស។', NULL, '["\\(150\\ \\text{cm}^2\\)", "\\(180\\ \\text{cm}^2\\)", "\\(90\\ \\text{cm}^2\\)", "\\(60\\ \\text{cm}^2\\)"]', 1, NULL, 2, 'mcq', 'បរិមាត្របាត ៖ \(p = 3 \times 5 = 15\ \text{cm} \Rightarrow S_L = 15 \times 12 = 180\ \text{cm}^2\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9713, 'ពីរ៉ាមីតទៀងទាត់មួយមានបាតជាការេជ្រុង \(6\ \text{cm}\) និងកម្ពស់ \(10\ \text{cm}\)។ គណនាមាឌនៃពីរ៉ាមីតនោះ។', NULL, '["\\(60\\ \\text{cm}^3\\)", "\\(360\\ \\text{cm}^3\\)", "\\(180\\ \\text{cm}^3\\)", "\\(120\\ \\text{cm}^3\\)"]', 3, NULL, 2, 'mcq', 'ផ្ទៃបាត ៖ \(S_B = 6^2 = 36\ \text{cm}^2 \Rightarrow V = \dfrac{1}{3} \times 36 \times 10 = 120\ \text{cm}^3\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9714, 'ពីរ៉ាមីតទៀងទាត់មួយមានបាតជាការេជ្រុង \(8\ \text{cm}\) និងអាប៉ូតែម \(a = 5\ \text{cm}\)។ គណនាផ្ទៃក្រឡាខាងរបស់វា។', NULL, '["\\(40\\ \\text{cm}^2\\)", "\\(144\\ \\text{cm}^2\\)", "\\(80\\ \\text{cm}^2\\)", "\\(160\\ \\text{cm}^2\\)"]', 2, NULL, 2, 'mcq', 'បរិមាត្របាត ៖ \(p = 4 \times 8 = 32\ \text{cm} \Rightarrow S_L = \dfrac{1}{2} \times 32 \times 5 = 80\ \text{cm}^2\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9715, 'កោនមួយមានកាំបាត \(r = 3\ \text{cm}\) និងជននី \(l = 5\ \text{cm}\)។ គណនាផ្ទៃក្រឡាខាងជាអនុគមន៍នៃ \(\pi\)។', NULL, '["\\(30\\pi\\ \\text{cm}^2\\)", "\\(15\\pi\\ \\text{cm}^2\\)", "\\(9\\pi\\ \\text{cm}^2\\)", "\\(24\\pi\\ \\text{cm}^2\\)"]', 1, NULL, 2, 'mcq', '\(S_L = \pi r l = \pi \times 3 \times 5 = 15\pi\ \text{cm}^2\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9716, 'កោនមួយមានកាំបាត \(r = 4\ \text{cm}\) និងជននី \(l = 6\ \text{cm}\)។ គណនាផ្ទៃក្រឡាទាំងអស់នៃកោនជាអនុគមន៍នៃ \(\pi\)។', NULL, '["\\(40\\pi\\ \\text{cm}^2\\)", "\\(16\\pi\\ \\text{cm}^2\\)", "\\(48\\pi\\ \\text{cm}^2\\)", "\\(24\\pi\\ \\text{cm}^2\\)"]', 0, NULL, 2, 'mcq', '\(S_T = \pi r l + \pi r^2 = \pi(4)(6) + \pi(4^2) = 24\pi + 16\pi = 40\pi\ \text{cm}^2\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9717, 'កោនមួយមានកាំបាត \(r = 6\ \text{cm}\) និងកម្ពស់ \(h = 10\ \text{cm}\)។ គណនាមាឌកោនជាអនុគមន៍នៃ \(\pi\)។', NULL, '["\\(60\\pi\\ \\text{cm}^3\\)", "\\(180\\pi\\ \\text{cm}^3\\)", "\\(120\\pi\\ \\text{cm}^3\\)", "\\(360\\pi\\ \\text{cm}^3\\)"]', 2, NULL, 2, 'mcq', '\(V = \dfrac{1}{3} \pi r^2 h = \dfrac{1}{3} \pi (36)(10) = 120\pi\ \text{cm}^3\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9718, 'កោនមួយមានកាំបាត \(r = 6\ \text{cm}\) និងកម្ពស់ \(h = 8\ \text{cm}\)។ គណនាប្រវែងជននី \(l\) នៃកោន។', NULL, '["\\(10\\ \\text{cm}\\)", "\\(12\\ \\text{cm}\\)", "\\(\\sqrt{28}\\ \\text{cm}\\)", "\\(14\\ \\text{cm}\\)"]', 0, NULL, 2, 'mcq', '\(l = \sqrt{r^2 + h^2} = \sqrt{6^2 + 8^2} = \sqrt{36 + 64} = 10\ \text{cm}\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9719, 'ស៊ីឡាំងមួយមានកាំបាត \(r = 5\ \text{cm}\) និងកម្ពស់ \(h = 12\ \text{cm}\)។ គណនាមាឌស៊ីឡាំងជាអនុគមន៍នៃ \(\pi\)។', NULL, '["\\(600\\pi\\ \\text{cm}^3\\)", "\\(300\\pi\\ \\text{cm}^3\\)", "\\(60\\pi\\ \\text{cm}^3\\)", "\\(150\\pi\\ \\text{cm}^3\\)"]', 1, NULL, 2, 'mcq', '\(V = \pi r^2 h = \pi (5^2)(12) = 300\pi\ \text{cm}^3\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9720, 'ស៊ីឡាំងមួយមានកាំបាត \(r = 7\ \text{cm}\) និងកម្ពស់ \(h = 10\ \text{cm}\)។ គណនាផ្ទៃក្រឡាខាង (យក \(\pi pprox \dfrac{22}{7}\))។', NULL, '["\\(440\\ \\text{cm}^2\\)", "\\(154\\ \\text{cm}^2\\)", "\\(880\\ \\text{cm}^2\\)", "\\(220\\ \\text{cm}^2\\)"]', 0, NULL, 2, 'mcq', '\(S_L = 2\pi r h = 2 \times \dfrac{22}{7} \times 7 \times 10 = 440\ \text{cm}^2\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9721, 'គូបមួយមានមាឌ \(64\ \text{cm}^3\)។ គណនាផ្ទៃក្រឡាសរុបនៃគូបនោះ។', NULL, '["\\(24\\ \\text{cm}^2\\)", "\\(96\\ \\text{cm}^2\\)", "\\(64\\ \\text{cm}^2\\)", "\\(16\\ \\text{cm}^2\\)"]', 1, NULL, 2, 'mcq', 'គែម ៖ \(a = \sqrt[3]{64} = 4\ \text{cm} \Rightarrow S = 6a^2 = 6 \times 16 = 96\ \text{cm}^2\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9722, 'អាងស្តុកទឹកមួយរាងប្រលេឡេពីប៉ែតកែងមានវិមាត្រ \(2\ \text{m} \times 1.5\ \text{m} \times 1\ \text{m}\)។ តើអាងនេះអាចផ្ទុកទឹកបានប៉ុន្មានលីត្រ?', NULL, '["\\(30\\,000\\ \\text{L}\\)", "\\(3\\,000\\ \\text{L}\\)", "\\(300\\ \\text{L}\\)", "\\(30\\ \\text{L}\\)"]', 1, NULL, 2, 'mcq', '\(V = 2 \times 1.5 \times 1 = 3\ \text{m}^3\)។ ដោយ \(1\ \text{m}^3 = 1\,000\ \text{L} \Rightarrow 3\,000\ \text{L}\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9723, 'ពីរ៉ាមីតទៀងទាត់មួយមានបាតជាការេជ្រុង \(10\ \text{cm}\) និងផ្ទៃក្រឡាខាង \(260\ \text{cm}^2\)។ គណនាផ្ទៃក្រឡាទាំងអស់នៃពីរ៉ាមីត។', NULL, '["\\(460\\ \\text{cm}^2\\)", "\\(360\\ \\text{cm}^2\\)", "\\(310\\ \\text{cm}^2\\)", "\\(270\\ \\text{cm}^2\\)"]', 1, NULL, 2, 'mcq', 'ផ្ទៃបាត ៖ \(S_B = 10^2 = 100\ \text{cm}^2 \Rightarrow S_T = S_L + S_B = 260 + 100 = 360\ \text{cm}^2\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9724, 'ស៊ីឡាំងមួយ និងកោនមួយមានកាំបាត \(r\) ដូចគ្នា និងកម្ពស់ \(h\) ដូចគ្នា។ តើផលធៀបមាឌកោនធៀបនឹងមាឌស៊ីឡាំងស្មើនឹងប៉ុន្មាន?', NULL, '["\\(\\dfrac{2}{3}\\)", "\\(\\dfrac{1}{2}\\)", "\\(\\dfrac{1}{3}\\)", "\\(3\\)"]', 2, NULL, 2, 'mcq', '\(\dfrac{V_{\text{កោន}}}{V_{\text{ស៊ីឡាំង}}} = \dfrac{\frac{1}{3}\pi r^2 h}{\pi r^2 h} = \dfrac{1}{3}\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9725, 'ពីរ៉ាមីតទៀងទាត់មួយមានបាតជាការេជ្រុង \(12\ \text{cm}\) និងកម្ពស់ \(8\ \text{cm}\)។ គណនាប្រវែងអាប៉ូតែម \(a\) នៃពីរ៉ាមីតនោះ។', NULL, '["\\(6\\ \\text{cm}\\)", "\\(12\\ \\text{cm}\\)", "\\(14\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)"]', 3, NULL, 3, 'mcq', 'ចម្ងាយពីផ្ចិតបាតទៅជ្រុងគឺ \(r = \dfrac{12}{2} = 6\ \text{cm} \Rightarrow a = \sqrt{8^2 + 6^2} = 10\ \text{cm}\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'hard', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9726, 'ពីរ៉ាមីតទៀងទាត់មានបាតជាការេជ្រុង \(16\ \text{cm}\) និងកម្ពស់ \(6\ \text{cm}\)។ គណនាផ្ទៃក្រឡាទាំងអស់នៃពីរ៉ាមីត។', NULL, '["\\(320\\ \\text{cm}^2\\)", "\\(576\\ \\text{cm}^2\\)", "\\(256\\ \\text{cm}^2\\)", "\\(512\\ \\text{cm}^2\\)"]', 1, NULL, 3, 'mcq', '\(a = \sqrt{6^2 + 8^2} = 10\ \text{cm} \Rightarrow S_L = \dfrac{1}{2}(64)(10) = 320\ \text{cm}^2\); \(S_B = 256 \Rightarrow S_T = 576\ \text{cm}^2\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'hard', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9727, 'កោនមួយមានកាំបាត \(r = 5\ \text{cm}\) និងជននី \(l = 13\ \text{cm}\)។ គណនាមាឌកោនជាអនុគមន៍នៃ \(\pi\)។', NULL, '["\\(100\\pi\\ \\text{cm}^3\\)", "\\(325\\pi\\ \\text{cm}^3\\)", "\\(300\\pi\\ \\text{cm}^3\\)", "\\(150\\pi\\ \\text{cm}^3\\)"]', 0, NULL, 3, 'mcq', '\(h = \sqrt{13^2 - 5^2} = 12\ \text{cm} \Rightarrow V = \dfrac{1}{3} \pi (25)(12) = 100\pi\ \text{cm}^3\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'hard', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9728, 'ព្រីសទៀងទាត់មួយមានកម្ពស់ \(10\ \text{cm}\) និងបាតជាឆកោណទៀងទាត់ជ្រុង \(4\ \text{cm}\)។ គណនាមាឌនៃព្រីសជាទម្រង់រ៉ាឌីកាល់សម្រួល។', NULL, '["\\(240\\sqrt{3}\\ \\text{cm}^3\\)", "\\(120\\sqrt{3}\\ \\text{cm}^3\\)", "\\(240\\ \\text{cm}^3\\)", "\\(480\\sqrt{3}\\ \\text{cm}^3\\)"]', 0, NULL, 3, 'mcq', 'ផ្ទៃបាត ៖ \(S_B = 6 \times \left(\dfrac{\sqrt{3}}{4} \times 16\right) = 24\sqrt{3}\ \text{cm}^2 \Rightarrow V = 24\sqrt{3} \times 10 = 240\sqrt{3}\ \text{cm}^3\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'hard', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9729, 'វត្ថុរឹងមួយផ្សំឡើងដោយស៊ីឡាំងកម្ពស់ \(12\ \text{cm}\) និងកោននៅពីលើកម្ពស់ \(3\ \text{cm}\) ដោយមានកាំបាតរួម \(r = 4\ \text{cm}\)។ គណនាមាឌសរុបជាអនុគមន៍នៃ \(\pi\)។', NULL, '["\\(208\\pi\\ \\text{cm}^3\\)", "\\(192\\pi\\ \\text{cm}^3\\)", "\\(224\\pi\\ \\text{cm}^3\\)", "\\(240\\pi\\ \\text{cm}^3\\)"]', 0, NULL, 3, 'mcq', '\(V_1 = \pi (16)(12) = 192\pi\); \(V_2 = \dfrac{1}{3} \pi (16)(3) = 16\pi \Rightarrow V = 192\pi + 16\pi = 208\pi\ \text{cm}^3\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'hard', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9730, 'បំពង់ដែកស៊ីឡាំងប្រហោងមួយមានកម្ពស់ \(50\ \text{cm}\), កាំក្រៅ \(R = 6\ \text{cm}\) និងកាំក្នុង \(r = 4\ \text{cm}\)។ គណនាមាឌដែកពិតប្រាកដជាអនុគមន៍នៃ \(\pi\)។', NULL, '["\\(1\\,000\\pi\\ \\text{cm}^3\\)", "\\(500\\pi\\ \\text{cm}^3\\)", "\\(800\\pi\\ \\text{cm}^3\\)", "\\(2\\,000\\pi\\ \\text{cm}^3\\)"]', 0, NULL, 3, 'mcq', '\(V = \pi(R^2 - r^2)h = \pi(36 - 16)(50) = 1\,000\pi\ \text{cm}^3\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'hard', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9731, 'ស៊ីឡាំងមួយមានកម្ពស់ \(h = 10\ \text{cm}\) និងកាំបាត \(r = 5\ \text{cm}\)។ គេទម្លាក់ដុំដែកមួយចូលធ្វើឱ្យទឹកហៀរចេញ \(25\%\) នៃចំណុះស៊ីឡាំង។ តើដុំដែកនោះមានមាឌប៉ុន្មានជាអនុគមន៍នៃ \(\pi\)?', NULL, '["\\(50\\pi\\ \\text{cm}^3\\)", "\\(125\\pi\\ \\text{cm}^3\\)", "\\(250\\pi\\ \\text{cm}^3\\)", "\\(62.5\\pi\\ \\text{cm}^3\\)"]', 3, NULL, 3, 'mcq', '\(V = \pi (25)(10) = 250\pi \Rightarrow V_{\text{ដែក}} = 250\pi \times 0.25 = 62.5\pi\ \text{cm}^3\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'hard', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9732, 'មួកខួបកំណើតមួយរាងកោនមានកាំបាត \(7\ \text{cm}\) និងជននី \(25\ \text{cm}\)។ គណនាផ្ទៃក្រដាសរឹងដែលត្រូវប្រើធ្វើមួកមួយនេះ (មិនគិតបាត, យក \(\pi pprox \dfrac{22}{7}\))។', NULL, '["\\(550\\ \\text{cm}^2\\)", "\\(350\\ \\text{cm}^2\\)", "\\(1\\,100\\ \\text{cm}^2\\)", "\\(704\\ \\text{cm}^2\\)"]', 0, NULL, 3, 'mcq', '\(S_L = \pi r l = \dfrac{22}{7} \times 7 \times 25 = 550\ \text{cm}^2\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'pisa', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9733, 'តង់បោះជំរំមួយរាងកោនមានកម្ពស់ \(2.4\ \text{m}\) និងកាំបាត \(0.7\ \text{m}\)។ គណនាផ្ទៃក្រណាត់តង់ដែលត្រូវប្រើធ្វើដំបូលជុំវិញ (យក \(\pi pprox \dfrac{22}{7}\))។', NULL, '["\\(11\\ \\text{m}^2\\)", "\\(4.8\\ \\text{m}^2\\)", "\\(5.5\\ \\text{m}^2\\)", "\\(7.04\\ \\text{m}^2\\)"]', 2, NULL, 3, 'mcq', '\(l = \sqrt{2.4^2 + 0.7^2} = 2.5\ \text{m} \Rightarrow S_L = \dfrac{22}{7} \times 0.7 \times 2.5 = 5.5\ \text{m}^2\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'pisa', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9734, 'ស៊ីឡូស្តុកស្រូវមួយផ្នែកខាងក្រោមជារាងស៊ីឡាំងកម្ពស់ \(10\ \text{m}\) និងកាំ \(3\ \text{m}\)។ គណនាមាឌស្តុកនៃផ្នែកស៊ីឡាំងនោះ (យក \(\pi pprox 3.14\))។', NULL, '["\\(282.6\\ \\text{m}^3\\)", "\\(565.2\\ \\text{m}^3\\)", "\\(188.4\\ \\text{m}^3\\)", "\\(94.2\\ \\text{m}^3\\)"]', 0, NULL, 3, 'mcq', '\(V = 3.14 \times 3^2 \times 10 = 3.14 \times 90 = 282.6\ \text{m}^3\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'pisa', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9735, 'នំកោនការ៉េមមួយមានកាំមាត់ \(3\ \text{cm}\) និងជម្រៅកម្ពស់ \(14\ \text{cm}\)។ គណនាមាឌការ៉េមរលាយដែលអាចបំពេញក្នុងនំនោះបាន (យក \(\pi pprox \dfrac{22}{7}\))។', NULL, '["\\(132\\ \\text{cm}^3\\)", "\\(396\\ \\text{cm}^3\\)", "\\(66\\ \\text{cm}^3\\)", "\\(264\\ \\text{cm}^3\\)"]', 0, NULL, 3, 'mcq', '\(V = \dfrac{1}{3} \times \dfrac{22}{7} \times 3^2 \times 14 = \dfrac{1}{3} \times 22 \times 9 \times 2 = 132\ \text{cm}^3\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'pisa', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9736, 'ប្រអប់កាដូរាងគូបមួយមានរង្វាស់គែម \(20\ \text{cm}\)។ បើគេចង់ខ្ចប់ប្រអប់នេះដោយប្រើក្រដាសកាដូបូកបន្ថែម \(10\%\) សម្រាប់ផ្នត់គែម តើត្រូវប្រើក្រដាសផ្ទៃប៉ុន្មាន?', NULL, '["\\(2\\,880\\ \\text{cm}^2\\)", "\\(2\\,640\\ \\text{cm}^2\\)", "\\(2\\,400\\ \\text{cm}^2\\)", "\\(4\\,800\\ \\text{cm}^2\\)"]', 1, NULL, 3, 'mcq', '\(S = 6 \times 20^2 = 2\,400\ \text{cm}^2 \Rightarrow S_{\text{ក្រដាស}} = 2\,400 \times 1.10 = 2\,640\ \text{cm}^2\)', 'រូបធរណីមាត្រមានវិមាត្របី', 'pisa', 1, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9737, 'ព្រីសត្រង់មួយមានកម្ពស់ \(h = 10\ \text{cm}\) និងបាតជាត្រីកោណកែងដែលមានជ្រុងមុំកែង \(a = 3\ \text{cm}\) និង \(b = 4\ \text{cm}\)។
ក. គណនាផ្ទៃក្រឡាបាត \(S_B\) នៃព្រីស។
ខ. សរសេររូបមន្ត និងគណនាមាឌ \(V\) នៃព្រីស។', 'g8-fbbe001236.svg', '[]', 0, NULL, 5, 'writing', 'ក. ផ្ទៃបាត ៖ \(S_B = \dfrac{a \times b}{2} = \dfrac{3 \times 4}{2} = 6\ \text{cm}^2\) (2 ពិន្ទុ)
ខ. រូបមន្តមាឌព្រីស ៖ \(V = S_B \times h\) (1 ពិន្ទុ)
ជំនួសតម្លៃ ៖ \(V = 6 \times 10 = 60\ \text{cm}^3\) (2 ពិន្ទុ)', 'រូបធរណីមាត្រមានវិមាត្របី', 'easy', 0, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9738, 'កោនមួយមានកាំបាត \(r = 6\ \text{cm}\) និងកម្ពស់ \(h = 8\ \text{cm}\)។
ក. គណនាប្រវែងជននី \(l\) នៃកោន។
ខ. គណនាផ្ទៃក្រឡាខាង \(S_L\) ជាអនុគមន៍នៃ \(\pi\)។
គ. គណនាមាឌ \(V\) នៃកោនជាអនុគមន៍នៃ \(\pi\)។', 'g8-b43b1cdb6c.svg', '[]', 0, NULL, 5, 'writing', 'ក. តាមពីតាក័រ ៖ \(l = \sqrt{r^2 + h^2} = \sqrt{6^2 + 8^2} = \sqrt{100} = 10\ \text{cm}\) (2 ពិន្ទុ)
ខ. ផ្ទៃក្រឡាខាង ៖ \(S_L = \pi r l = \pi \times 6 \times 10 = 60\pi\ \text{cm}^2\) (1 ពិន្ទុ)
គ. មាឌកោន ៖ \(V = \dfrac{1}{3} \pi r^2 h = \dfrac{1}{3} \pi (36)(8) = 96\pi\ \text{cm}^3\) (2 ពិន្ទុ)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 0, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9739, 'ពីរ៉ាមីតទៀងទាត់មួយមានបាតជាការេជ្រុង \(10\ \text{cm}\) និងអាប៉ូតែម \(a = 13\ \text{cm}\)។
ក. គណនាបរិមាត្របាត \(p\) និងផ្ទៃក្រឡាបាត \(S_B\)។
ខ. គណនាផ្ទៃក្រឡាខាង \(S_L\) នៃពីរ៉ាមីត។
គ. គណនាផ្ទៃក្រឡាទាំងអស់ \(S_T\) នៃពីរ៉ាមីត។', 'g8-79409e22ad.svg', '[]', 0, NULL, 5, 'writing', 'ក. បរិមាត្របាត ៖ \(p = 4 \times 10 = 40\ \text{cm}\); ផ្ទៃបាត ៖ \(S_B = 10^2 = 100\ \text{cm}^2\) (2 ពិន្ទុ)
ខ. ផ្ទៃក្រឡាខាង ៖ \(S_L = \dfrac{1}{2} p \times a = \dfrac{1}{2} \times 40 \times 13 = 260\ \text{cm}^2\) (2 ពិន្ទុ)
គ. ផ្ទៃក្រឡាទាំងអស់ ៖ \(S_T = S_L + S_B = 260 + 100 = 360\ \text{cm}^2\) (1 ពិន្ទុ)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 0, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9740, 'ស៊ីឡាំងមួយមានកាំបាត \(r = 7\ \text{cm}\) និងកម្ពស់ \(h = 15\ \text{cm}\)។
ក. គណនាផ្ទៃក្រឡាខាង \(S_L\) នៃស៊ីឡាំង (យក \(\pi pprox \dfrac{22}{7}\))។
ខ. គណនាផ្ទៃក្រឡាទាំងអស់ \(S_T\) នៃស៊ីឡាំង។
គ. គណនាមាឌ \(V\) នៃស៊ីឡាំង។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(S_L = 2\pi r h = 2 \times \dfrac{22}{7} \times 7 \times 15 = 660\ \text{cm}^2\) (2 ពិន្ទុ)
ខ. ផ្ទៃបាតពីរ ៖ \(2S_B = 2 \times \dfrac{22}{7} \times 49 = 308\ \text{cm}^2 \Rightarrow S_T = 660 + 308 = 968\ \text{cm}^2\) (1 ពិន្ទុ)
គ. មាឌ ៖ \(V = \pi r^2 h = \dfrac{22}{7} \times 49 \times 15 = 154 \times 15 = 2\,310\ \text{cm}^3\) (2 ពិន្ទុ)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 0, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9741, 'ព្រីសត្រង់មួយមានកម្ពស់ \(12\ \text{cm}\) និងបាតជាត្រីកោណសម័ង្សជ្រុង \(6\ \text{cm}\)។
ក. គណនាផ្ទៃក្រឡាខាង \(S_L\) នៃព្រីស។
ខ. គណនាផ្ទៃក្រឡាបាត \(S_B\) មួយជាទម្រង់រ៉ាឌីកាល់សម្រួល។
គ. គណនាផ្ទៃក្រឡាទាំងអស់ \(S_T\) នៃព្រីស។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. បរិមាត្របាត ៖ \(p = 3 \times 6 = 18\ \text{cm} \Rightarrow S_L = 18 \times 12 = 216\ \text{cm}^2\) (2 ពិន្ទុ)
ខ. ផ្ទៃបាត ៖ \(S_B = \dfrac{\sqrt{3}}{4} \times 6^2 = 9\sqrt{3}\ \text{cm}^2\) (1 ពិន្ទុ)
គ. ផ្ទៃទាំងអស់ ៖ \(S_T = S_L + 2S_B = 216 + 18\sqrt{3}\ \text{cm}^2\) (2 ពិន្ទុ)', 'រូបធរណីមាត្រមានវិមាត្របី', 'medium', 0, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9742, 'ពីរ៉ាមីតទៀងទាត់មួយមានបាតជាការេជ្រុង \(16\ \text{cm}\) និងអាប៉ូតែម \(a = 17\ \text{cm}\)។
ក. គណនាចម្ងាយពីផ្ចិតបាតទៅជ្រុងបាត \(r\)។
ខ. គណនាកម្ពស់ \(h\) នៃពីរ៉ាមីត។
គ. គណនាមាឌ \(V\) នៃពីរ៉ាមីត។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(r = \dfrac{16}{2} = 8\ \text{cm}\) (1 ពិន្ទុ)
ខ. ក្នុងត្រីកោណកែង ៖ \(h = \sqrt{a^2 - r^2} = \sqrt{17^2 - 8^2} = \sqrt{289 - 64} = \sqrt{225} = 15\ \text{cm}\) (2 ពិន្ទុ)
គ. ផ្ទៃបាត \(S_B = 16^2 = 256\ \text{cm}^2 \Rightarrow V = \dfrac{1}{3} \times 256 \times 15 = 1\,280\ \text{cm}^3\) (2 ពិន្ទុ)', 'រូបធរណីមាត្រមានវិមាត្របី', 'hard', 0, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9743, 'ក្រដាសមួយផ្ទាំងជារាងចម្រៀករង្វង់មានកាំ \(R = 10\ \text{cm}\) និងមុំផ្ចិត \(216^\circ\) ត្រូវបានរុំបង្កើតជាកោនមួយ។
ក. គណនាប្រវែងធ្នូនៃចម្រៀករង្វង់ (យក \(\pi\))។
ខ. បង្ហាញថាប្រវែងធ្នូនេះស្មើនឹងបរិមាត្របាតកោន រួចទាញរកកាំបាត \(r\)។
គ. គណនាកម្ពស់ \(h\) និងមាឌ \(V\) នៃកោននោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ប្រវែងធ្នូ ៖ \(L = \dfrac{2\pi (10) \times 216}{360} = 12\pi\ \text{cm}\) (1 ពិន្ទុ)
ខ. បរិមាត្របាតកោន \(2\pi r = 12\pi \Rightarrow r = 6\ \text{cm}\) (ជននីកោនគឺ \(l = R = 10\ \text{cm}\)) (2 ពិន្ទុ)
គ. កម្ពស់ \(h = \sqrt{10^2 - 6^2} = 8\ \text{cm} \Rightarrow V = \dfrac{1}{3}\pi (36)(8) = 96\pi\ \text{cm}^3\) (2 ពិន្ទុ)', 'រូបធរណីមាត្រមានវិមាត្របី', 'hard', 0, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9744, 'ស្នូកទឹកមួយរាងព្រីសត្រង់មានបាតជាចតុកោណព្នាយសមបាត ៖ បាតតូច \(0.6\ \text{m}\), បាតធំ \(1.2\ \text{m}\), ជម្រៅ \(0.8\ \text{m}\) និងប្រវែងស្នូក \(3\ \text{m}\)។
ក. គណនាផ្ទៃក្រឡាបាតចតុកោណព្នាយ។
ខ. គណនាមាឌទឹកអតិបរិមាដែលស្នូកអាចផ្ទុកបានគិតជាម៉ែត្រគូប។
គ. បំលែងមាឌទឹកនោះទៅជាលីត្រ (\(\text{L}\))។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផ្ទៃបាតព្នាយ ៖ \(S_B = \dfrac{(0.6 + 1.2) \times 0.8}{2} = \dfrac{1.8 \times 0.8}{2} = 0.72\ \text{m}^2\) (2 ពិន្ទុ)
ខ. មាឌស្នូក ៖ \(V = S_B \times h = 0.72 \times 3 = 2.16\ \text{m}^3\) (1 ពិន្ទុ)
គ. ដោយ \(1\ \text{m}^3 = 1\,000\ \text{L} \Rightarrow 2.16 \times 1\,000 = 2\,160\ \text{L}\) (2 ពិន្ទុ)', 'រូបធរណីមាត្រមានវិមាត្របី', 'hard', 0, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9745, 'គេយកដុំដែកទម្រង់គូបជ្រុង \(a = 6\ \text{cm}\) ទៅរំលាយរួចចាក់ពុម្ពធ្វើជាកោនមួយដែលមានកាំបាត \(r = 6\ \text{cm}\)។
ក. គណនាមាឌនៃដុំដែកគូបដើម។
ខ. គណនាកម្ពស់ \(h\) នៃកោនថ្មី (ដឹងថាមាឌមិនបាត់បង់, យក \(\pi pprox 3.14\))។
គ. ប្រៀបធៀបកម្ពស់កោនធៀបនឹងជ្រុងគូប។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. មាឌគូប ៖ \(V = 6^3 = 216\ \text{cm}^3\) (1 ពិន្ទុ)
ខ. មាឌកោន ៖ \(V = \dfrac{1}{3} \pi r^2 h \Rightarrow 216 = \dfrac{1}{3} \times 3.14 \times 36 \times h = 37.68 h\) (2 ពិន្ទុ)
ទាញបាន \(h = \dfrac{216}{37.68} pprox 5.73\ \text{cm}\) (1 ពិន្ទុ)
គ. កម្ពស់កោន \(h pprox 5.73\ \text{cm} < 6\ \text{cm}\) (ទាបជាងជ្រុងគូបបន្តិច) (1 ពិន្ទុ)', 'រូបធរណីមាត្រមានវិមាត្របី', 'hard', 0, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9746, 'អាងស្តុកទឹកបេតុងរាងប្រលេឡេពីប៉ែតកែងមួយមានវិមាត្រខាងក្នុង ៖ បណ្តោយ \(4\ \text{m}\), ទទឹង \(2.5\ \text{m}\) និងកម្ពស់ \(2\ \text{m}\)។
ក. គណនាចំណុះទឹកអតិបរិមានៃអាងគិតជាលីត្រ។
ខ. បើគេចង់បូកស៊ីម៉ង់តិ៍ផ្ទៃជញ្ជាំងខាងក្នុងទាំង ៤ និងបាតក្រោម គណនាផ្ទៃក្រឡាដែលត្រូវបូក។
គ. បើថ្លៃបូកស៊ីម៉ង់តិ៍គឺ \(6\$/\text{m}^2\) គណនាថ្លៃចំណាយសរុប។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. មាឌអាង ៖ \(V = 4 \times 2.5 \times 2 = 20\ \text{m}^3 = 20\,000\ \text{L}\) (2 ពិន្ទុ)
ខ. ផ្ទៃបាត ៖ \(4 \times 2.5 = 10\ \text{m}^2\); ផ្ទៃជញ្ជាំង ៤ ៖ \(2(4 + 2.5) \times 2 = 26\ \text{m}^2 \Rightarrow S = 10 + 26 = 36\ \text{m}^2\) (2 ពិន្ទុ)
គ. ថ្លៃចំណាយ ៖ \(36 \times 6 = 216\$\) (1 ពិន្ទុ)', 'រូបធរណីមាត្រមានវិមាត្របី', 'pisa', 0, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9747, 'រោងសៀកមួយមានដំបូលរាងកោនដែលមានកាំបាត \(14\ \text{m}\) និងកម្ពស់ \(4.8\ \text{m}\)។
ក. គណនាប្រវែងជននី \(l\) នៃដំបូលកោន។
ខ. គណនាផ្ទៃក្រណាត់តង់ដែលត្រូវប្រើសម្រាប់ដំបូល (យក \(\pi pprox \dfrac{22}{7}\))។
គ. បើក្រណាត់តង់ ១ ម៉ែត្រការេមានតម្លៃ \(12\$\) គណនាថ្លៃទិញក្រណាត់តង់ដំបូល។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ជននី ៖ \(l = \sqrt{14^2 + 4.8^2} = \sqrt{196 + 23.04} = \sqrt{219.04} = 14.8\ \text{m}\) (2 ពិន្ទុ)
ខ. ផ្ទៃដំបូលកោន ៖ \(S_L = \pi r l = \dfrac{22}{7} \times 14 \times 14.8 = 44 \times 14.8 = 651.2\ \text{m}^2\) (2 ពិន្ទុ)
គ. ថ្លៃក្រណាត់តង់ ៖ \(651.2 \times 12 = 7\,814.40\$\) (1 ពិន្ទុ)', 'រូបធរណីមាត្រមានវិមាត្របី', 'pisa', 0, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9748, 'ស៊ីឡូស្តុកគ្រាប់ធញ្ញជាតិមួយរាងស៊ីឡាំងមានកាំបាត \(4\ \text{m}\) និងកម្ពស់ \(15\ \text{m}\)។
ក. គណនាមាឌស៊ីឡូស្តុកនោះ (យក \(\pi pprox 3.14\))។
ខ. បើស្រូវ ១ ម៉ែត្រគូប មានទម្ងន់ \(0.75\ \text{តោន}\) គណនាទម្ងន់ស្រូវអតិបរិមាដែលអាចស្តុកបាន។
គ. បើឡានដឹកស្រូវមួយជើងអាចដឹកបាន \(15\ \text{តោន}\) តើត្រូវដឹកប៉ុន្មានជើងដើម្បីបំពេញស៊ីឡូនោះ?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. មាឌស៊ីឡូ ៖ \(V = 3.14 \times 4^2 \times 15 = 3.14 \times 16 \times 15 = 753.6\ \text{m}^3\) (2 ពិន្ទុ)
ខ. ទម្ងន់ស្រូវសរុប ៖ \(753.6 \times 0.75 = 565.2\ \text{តោន}\) (2 ពិន្ទុ)
គ. ចំនួនជើងឡាន ៖ \(\dfrac{565.2}{15} = 37.68 \Rightarrow 38\ \text{ជើង}\) (1 ពិន្ទុ)', 'រូបធរណីមាត្រមានវិមាត្របី', 'pisa', 0, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9749, 'រោងចក្រផលិតប្រអប់ក្រដាសមួយចង់ផលិតប្រអប់រាងប្រលេឡេពីប៉ែតកែងមានវិមាត្រ \(30\ \text{cm} \times 20\ \text{cm} \times 15\ \text{cm}\) ចំនួន ១០០០ ប្រអប់។
ក. គណនាផ្ទៃក្រឡាទាំងអស់នៃប្រអប់មួយ។
ខ. ដោយគិតបន្ថែម \(15\%\) សម្រាប់កាត់គែមនិងបិទកាវ គណនាផ្ទៃក្រដាសរឹងសរុបសម្រាប់ ១ ប្រអប់។
គ. គណនាផ្ទៃក្រដាសរឹងសរុបគិតជាម៉ែត្រការេ (\(\text{m}^2\)) សម្រាប់ផលិត ១០០០ ប្រអប់។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផ្ទៃប្រអប់មួយ ៖ \(S_T = 2(30 \times 20 + 30 \times 15 + 20 \times 15) = 2(600 + 450 + 300) = 2\,700\ \text{cm}^2\) (2 ពិន្ទុ)
ខ. ផ្ទៃរួមបន្ថែម \(15\%\) ៖ \(2\,700 \times 1.15 = 3\,105\ \text{cm}^2\) (1 ពិន្ទុ)
គ. សម្រាប់ ១០០០ ប្រអប់ ៖ \(3\,105 \times 1\,000 = 3\,105\,000\ \text{cm}^2 = 310.5\ \text{m}^2\) (2 ពិន្ទុ)', 'រូបធរណីមាត្រមានវិមាត្របី', 'pisa', 0, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9750, 'អាងហែលទឹកមួយមានបណ្តោយ \(25\ \text{m}\), ទទឹង \(10\ \text{m}\) និងជម្រៅទឹកជាមធ្យម \(1.8\ \text{m}\)។
ក. គណនាមាឌទឹកក្នុងអាងគិតជាម៉ែត្រគូប។
ខ. គេប្រើម៉ាស៊ីនបូមទឹកដែលមានអានុភាពបូម \(50\ \text{m}^3/\text{h}\)។ តើត្រូវចំណាយពេលប៉ុន្មានម៉ោងដើម្បីបូមទឹកបំពេញអាង?
គ. បើតម្លៃទឹកស្អាតគឺ \(1\,500\ \text{រៀល/m}^3\) គណនាថ្លៃទឹកសរុបសម្រាប់បំពេញអាង។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. មាឌទឹក ៖ \(V = 25 \times 10 \times 1.8 = 450\ \text{m}^3\) (2 ពិន្ទុ)
ខ. រយៈពេលបូម ៖ \(T = \dfrac{450}{50} = 9\ \text{ម៉ោង}\) (2 ពិន្ទុ)
គ. ថ្លៃទឹកសរុប ៖ \(450 \times 1\,500 = 675\,000\ \text{រៀល}\) (1 ពិន្ទុ)', 'រូបធរណីមាត្រមានវិមាត្របី', 'pisa', 0, '8', 'រូបធរណីមាត្រមានវិមាត្របី', NULL, 0);
